import asyncio
import base64
import datetime
import json
import random
import sqlite3
import time
import uuid
from contextlib import asynccontextmanager
from typing import List, Optional, Union, Dict, Any, AsyncGenerator

import uvicorn
from fastapi import FastAPI, HTTPException, Request, Depends, BackgroundTasks
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import JSONResponse, StreamingResponse, HTMLResponse
from fastapi.security import HTTPBearer, HTTPAuthorizationCredentials
from pydantic import BaseModel, Field

DB_PATH = "perplexity_clone.db"

def get_db():
    conn = sqlite3.connect(DB_PATH, check_same_thread=False)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute("""
        CREATE TABLE IF NOT EXISTS users (
            id TEXT PRIMARY KEY,
            username TEXT UNIQUE,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
    """)
    cursor.execute("""
        CREATE TABLE IF NOT EXISTS tokens (
            token TEXT PRIMARY KEY,
            user_id TEXT,
            is_active BOOLEAN DEFAULT 1,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY(user_id) REFERENCES users(id)
        )
    """)
    cursor.execute("""
        CREATE TABLE IF NOT EXISTS jobs (
            id TEXT PRIMARY KEY,
            user_id TEXT,
            status TEXT,
            request_payload TEXT,
            result_payload TEXT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY(user_id) REFERENCES users(id)
        )
    """)
    conn.commit()
    conn.close()

@asynccontextmanager
async def lifespan(app: FastAPI):
    init_db()
    yield

app = FastAPI(lifespan=lifespan)
security = HTTPBearer()

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

class FileURL(BaseModel):
    url: str

class ContentItem(BaseModel):
    type: str
    text: Optional[str] = None
    file_url: Optional[FileURL] = None
    file_name: Optional[str] = None

class Message(BaseModel):
    role: str
    content: Union[str, List[ContentItem]]

class ChatRequest(BaseModel):
    model: str = "sonar-pro"
    messages: List[Message]
    max_tokens: Optional[int] = None
    temperature: float = 0.2
    top_p: float = 0.9
    return_citations: bool = False
    return_images: bool = False
    return_related_questions: bool = False
    search_domain_filter: Optional[List[str]] = None
    search_recency_filter: Optional[str] = None
    top_k: int = 0
    stream: bool = False
    presence_penalty: float = 0
    frequency_penalty: float = 1

class SearchRequest(BaseModel):
    query: str
    max_results: int = 10
    search_domain_filter: Optional[List[str]] = None
    search_recency_filter: Optional[str] = None

class TokenRequest(BaseModel):
    username: str

def get_current_user(credentials: HTTPAuthorizationCredentials = Depends(security)):
    token = credentials.credentials
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute("SELECT user_id FROM tokens WHERE token = ? AND is_active = 1", (token,))
    row = cursor.fetchone()
    conn.close()
    if not row:
        raise HTTPException(status_code=401, detail="Invalid or expired token")
    return row["user_id"]

def generate_deterministic_response(messages: List[Message], model: str) -> str:
    last_message = messages[-1]
    content_str = ""
    if isinstance(last_message.content, str):
        content_str = last_message.content
    else:
        for item in last_message.content:
            if item.type == "text":
                content_str += item.text + " "
            elif item.type == "file_url":
                content_str += "[FILE PROCESSED] "

    keywords = [w for w in content_str.split() if len(w) > 4]
    base_response = f"Analysis of the request regarding '{content_str[:50]}...' indicates several key factors. "

    if "code" in content_str.lower() or "function" in content_str.lower():
        base_response += "Here is the implementation based on the specifications provided. The logic ensures robustness and type safety.\n\n``````\n\nThe algorithm operates with O(n log n) complexity."
    elif "search" in content_str.lower() or "find" in content_str.lower():
        base_response += f"According to recent indices, the topic '{keywords[0] if keywords else 'requested'}' has shown significant relevance. Sources indicate a 15% increase in related activities over the last quarter."
    else:
        base_response += f"The {model} model has processed the input. Primary entities identified: {', '.join(keywords[:3])}. The context suggests a need for detailed breakdown of these components. 1. {keywords[0] if keywords else 'Item 1'}: Critical for structural integrity. 2. {keywords[1] if len(keywords)>1 else 'Item 2'}: Facilitates integration."

    return base_response

@app.post("/auth/token")
def generate_token(req: TokenRequest):
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute("SELECT id FROM users WHERE username = ?", (req.username,))
    user = cursor.fetchone()
    if not user:
        user_id = str(uuid.uuid4())
        cursor.execute("INSERT INTO users (id, username) VALUES (?, ?)", (user_id, req.username))
    else:
        user_id = user["id"]

    token = f"pplx-{uuid.uuid4().hex}"
    cursor.execute("INSERT INTO tokens (token, user_id) VALUES (?, ?)", (token, user_id))
    conn.commit()
    conn.close()
    return {"access_token": token, "token_type": "bearer"}

@app.post("/auth/revoke")
def revoke_token(credentials: HTTPAuthorizationCredentials = Depends(security)):
    token = credentials.credentials
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute("UPDATE tokens SET is_active = 0 WHERE token = ?", (token,))
    conn.commit()
    conn.close()
    return {"message": "Token revoked successfully"}

async def stream_generator(response_text: str, model: str, request_id: str):
    chunk_size = 10
    tokens = response_text.split(" ")

    for i in range(0, len(tokens), chunk_size):
        chunk = " ".join(tokens[i:i+chunk_size]) + " "
        data = {
            "id": request_id,
            "object": "chat.completion.chunk",
            "created": int(time.time()),
            "model": model,
            "choices": [
                {
                    "index": 0,
                    "delta": {"role": "assistant", "content": chunk},
                    "finish_reason": None
                }
            ]
        }
        yield f"data: {json.dumps(data)}\n\n"
        await asyncio.sleep(0.1)

    final_data = {
        "id": request_id,
        "object": "chat.completion.chunk",
        "created": int(time.time()),
        "model": model,
        "choices": [
            {
                "index": 0,
                "delta": {},
                "finish_reason": "stop"
            }
        ]
    }
    yield f"data: {json.dumps(final_data)}\n\n"

@app.post("/chat/completions")
async def chat_completions(req: ChatRequest, user_id: str = Depends(get_current_user)):
    request_id = str(uuid.uuid4())
    response_content = generate_deterministic_response(req.messages, req.model)

    if req.stream:
        return StreamingResponse(stream_generator(response_content, req.model, request_id), media_type="text/event-stream")

    citations = []
    if req.return_citations:
        citations = ["", ""]

    return {
        "id": request_id,
        "object": "chat.completion",
        "created": int(time.time()),
        "model": req.model,
        "choices": [
            {
                "index": 0,
                "message": {
                    "role": "assistant",
                    "content": response_content
                },
                "finish_reason": "stop"
            }
        ],
        "citations": citations,
        "usage": {
            "prompt_tokens": len(str(req.messages)),
            "completion_tokens": len(response_content),
            "total_tokens": len(str(req.messages)) + len(response_content)
        }
    }

async def process_async_job(job_id: str, req: ChatRequest):
    await asyncio.sleep(5)
    response_content = generate_deterministic_response(req.messages, req.model)
    conn = get_db()
    cursor = conn.cursor()
    result = {
        "id": job_id,
        "object": "chat.completion",
        "created": int(time.time()),
        "model": req.model,
        "choices": [
            {
                "index": 0,
                "message": {
                    "role": "assistant",
                    "content": response_content
                },
                "finish_reason": "stop"
            }
        ],
        "usage": {"total_tokens": 100}
    }
    cursor.execute(
        "UPDATE jobs SET status = ?, result_payload = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?",
        ("completed", json.dumps(result), job_id)
    )
    conn.commit()
    conn.close()

@app.post("/async/chat/completions")
async def async_chat_completions(req: ChatRequest, background_tasks: BackgroundTasks, user_id: str = Depends(get_current_user)):
    job_id = str(uuid.uuid4())
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute(
        "INSERT INTO jobs (id, user_id, status, request_payload) VALUES (?, ?, ?, ?)",
        (job_id, user_id, "pending", json.dumps(req.model_dump()))
    )
    conn.commit()
    conn.close()

    background_tasks.add_task(process_async_job, job_id, req)

    return {"id": job_id, "object": "chat.completion.async.job", "status": "pending"}

@app.get("/async/chat/completions")
def list_async_jobs(user_id: str = Depends(get_current_user)):
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute("SELECT id, status, created_at FROM jobs WHERE user_id = ? ORDER BY created_at DESC", (user_id,))
    rows = cursor.fetchall()
    conn.close()
    return [{"id": r["id"], "status": r["status"], "created_at": r["created_at"]} for r in rows]

@app.get("/async/chat/completions/{job_id}")
def get_async_job(job_id: str, user_id: str = Depends(get_current_user)):
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute("SELECT * FROM jobs WHERE id = ? AND user_id = ?", (job_id, user_id))
    row = cursor.fetchone()
    conn.close()

    if not row:
        raise HTTPException(status_code=404, detail="Job not found")

    response = {
        "id": row["id"],
        "status": row["status"],
        "created_at": row["created_at"]
    }

    if row["status"] == "completed" and row["result_payload"]:
        response["result"] = json.loads(row["result_payload"])

    return response

@app.post("/search")
def perform_search(req: SearchRequest, user_id: str = Depends(get_current_user)):
    results = []
    base_domains = ["wikipedia.org", "arxiv.org", "github.com", "nytimes.com", "stackoverflow.com"]
    for i in range(req.max_results):
        domain = random.choice(base_domains)
        results.append({
            "title": f"Result {i+1} for {req.query}",
            "url": f"' ', '_')}_{i}",
            "snippet": f"This is a comprehensive excerpt describing the nuances of {req.query}. It covers historical context, technical specifications, and future implications relevant to {domain}."
        })
    return {"results": results}

@app.get("/")
def serve_index():
    with open("index.html", "r", encoding="utf-8") as f:
        return HTMLResponse(content=f.read())

if __name__ == "__main__":
