            const input = document.getElementById('chat-input');
            const text = input.value;
            if(!text) return;

            const stream = document.getElementById('chat-stream').checked;
            const model = document.getElementById('chat-model').value;
            const history = document.getElementById('chat-history');

            const contentPayload = [];
            if (text) contentPayload.push({type: "text", text: text});
            if (currentFileBase64) contentPayload.push({type: "file_url", file_url: {url: currentFileBase64}});

            const userMsgDiv = document.createElement('div');
            userMsgDiv.className = 'message user';
            userMsgDiv.textContent = text + (currentFileBase64 ? ' [File Attached]' : '');
            history.appendChild(userMsgDiv);

            input.value = '';
            currentFileBase64 = null;
            document.getElementById('file-name-display').textContent = '';
            document.getElementById('chat-file').value = '';

            const assistantMsgDiv = document.createElement('div');
            assistantMsgDiv.className = 'message assistant';
            assistantMsgDiv.textContent = '...';
            history.appendChild(assistantMsgDiv);
            history.scrollTop = history.scrollHeight;

            try {
                const res = await fetch(`${apiBase}/chat/completions`, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'Authorization': `Bearer ${authToken}`
                    },
