                            }
                        }
                    }
                } else {
                    const data = await res.json();
                    assistantMsgDiv.textContent = data.choices[0].message.content;
                }
            } catch (err) {
                assistantMsgDiv.textContent = 'Error: ' + err.message;
            }
        }

        async function submitAsyncJob() {
            if(!authToken) return alert('Generate token first');
            const res = await fetch(`${apiBase}/async/chat/completions`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${authToken}`
                },
                body: JSON.stringify({
                    model: "sonar-pro",
                    messages: [{role: "user", content: "Async analysis request"}]
                })
            });
            await res.json();
            loadAsyncJobs();
        }

        async function loadAsyncJobs() {
            if(!authToken) return;
            const res = await fetch(`${apiBase}/async/chat/completions`, {
                headers: {'Authorization': `Bearer ${authToken}`}
            });
            const jobs = await res.json();
            const tbody = document.getElementById('async-jobs-list');
            tbody.innerHTML = jobs.map(j => `
                <tr>
                    <td>${j.id}</td>
                    <td>${j.created_at}</td>
                    <td><span class="badge badge-${j.status}">${j.status}</span></td>
                    <td>
                        <button class="btn btn-secondary" style="padding: 5px 10px; font-size: 0.8rem;" 
                                onclick="viewJobResult('${j.id}')">View</button>
                    </td>
                </tr>
            `).join('');
        }

        async function viewJobResult(id) {
            const res = await fetch(`${apiBase}/async/chat/completions/${id}`, {
                headers: {'Authorization': `Bearer ${authToken}`}
            });
            const data = await res.json();
            document.getElementById('job-result-content').textContent = JSON.stringify(data, null, 2);
            document.getElementById('job-modal').classList.add('open');
        }

        setInterval(() => {
            if(document.getElementById('async-panel').classList.contains('active') && authToken) {
                loadAsyncJobs();
            }
        }, 5000);
    </script>
</body>
</html>
